  return {
    btnTag: btn ? btn.tagName : null,
    btnText: btn ? btn.innerText.slice(0,80) : null,
    btnAria: btn ? btn.getAttribute('aria-expanded') : null,
    btnClass: btn ? btn.className : null,
    secClass: sec ? sec.className : null,
    secHtmlLen: sec ? sec.innerHTML.length : 0,
    hasM: sec ? /(^|[^A-Za-z])M([^A-Za-z]|$)/.test(sec.innerText) : false,
    secText: sec ? sec.innerText.slice(0, 400) : null,
    filterPanel: (() => { const f = document.querySelector('#filter, [class*="filter-modal"], [class*="FilterModal"]'); return f ? { cls: f.className, hidden: f.offsetParent === null, txt: f.innerText.slice(0,300) } : null; })(),
    checked: [...document.querySelectorAll('input[type="checkbox"]')].slice(0,20).map(i => ({id: i.id, name: i.name, value: i.value, checked: i.checked, vis: !!i.offsetParent}))
  };
});
return info;

const info = phi.js(() => {
  const btn = document.querySelector('#accordion-size');
  const out = { chain: [], sizes: [], colorLabels: [] };
  let el = btn;
  for (let i = 0; i < 6 && el; i++) {
    out.chain.push({ i, tag: el.tagName, cls: (el.className || '').slice(0, 120), childCount: el.children.length, txt: (el.innerText || '').slice(0, 200) });
    el = el.parentElement;
  }
  // the accordion container that holds both label and content
  const acc = btn.closest('.accordion, [class*="accordion"]');
  out.accCls = acc ? acc.className : null;
  out.accOuter = acc ? acc.outerHTML.slice(0, 1500) : null;
  document.querySelectorAll('input[id^="radio-size-"]').forEach(inp => {
    const lab = document.querySelector('label[for="' + inp.id + '"]');
    out.sizes.push({ id: inp.id, val: inp.value, checked: inp.checked, labelText: lab ? lab.innerText.trim() : null, labCls: lab ? lab.className.slice(0,80) : null, inpDisplay: getComputedStyle(inp).display, parentCls: inp.parentElement.className.slice(0,80) });
  });
  return out;
});
return info;

const probe = phi.js(() => {
  const btn = document.querySelector('#accordion-size');
  const b = btn.getBoundingClientRect();
  const cx = Math.round(b.left + b.width/2), cy = Math.round(b.top + b.height/2);
  const at = document.elementFromPoint(cx, cy);
  const content = document.querySelector('#accordion-size-content');
  return {
    atPoint: at ? { tag: at.tagName, cls: (at.className||'').toString().slice(0,100), txt: (at.innerText||'').slice(0,60) } : null,
    atIsBtnOrChild: at ? (btn === at || btn.contains(at)) : false,
    contentStyle: content ? { cs: getComputedStyle(content).cssText ? null : null, h: content.offsetHeight, overflow: getComputedStyle(content).overflow, maxH: getComputedStyle(content).maxHeight, display: getComputedStyle(content).display } : null,
    contentParentCls: content && content.parentElement ? (content.parentElement.className||'').toString().slice(0,100) : null,
    dupeIds: document.querySelectorAll('#accordion-size').length
  };
});
return probe;

