const probe = phi.js(() => {
  const out = {};
  // find elements whose text is exactly "Size" inside filter area
  const all = [...document.querySelectorAll('div,li,button,span,h3,h4,summary,a')];
  const sizeEls = all.filter(e => (e.innerText||'').trim() === 'Size' && e.children.length <= 2);
  out.sizeEls = sizeEls.slice(0,6).map(e => {
    const r = e.getBoundingClientRect();
    return { tag: e.tagName, cls: (e.className||'').toString().slice(0,60), rect: [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)], clickable: !!(r.width && r.height), parentCls: (e.parentElement.className||'').toString().slice(0,60) };
  });
  // is there any element containing "M" as size option in filters
  const inputs = [...document.querySelectorAll('input[type="checkbox"], input[type="radio"]')].slice(0,30).map(i => ({ name: i.name, value: i.value, id: i.id, checked: i.checked, vis: !!(i.offsetWidth||i.offsetHeight) }));
  out.inputs = inputs;
  out.inputCount = document.querySelectorAll('input').length;
  // filter panel container
  const panel = document.querySelector('[class*="filter" i][class*="panel" i], [class*="filter" i][class*="drawer" i], [role="dialog"]');
  out.panel = panel ? { cls: (panel.className||'').toString().slice(0,80), vis: !!(panel.offsetWidth||panel.offsetHeight), text: (panel.innerText||'').slice(0,300) } : null;
  out.dialogs = [...document.querySelectorAll('[role="dialog"]')].map(d => ({ cls:(d.className||'').toString().slice(0,50), vis: !!(d.offsetWidth||d.offsetHeight), t: (d.innerText||'').slice(0,80) }));
  return out;
});
