const probe = phi.js(() => {
  const out = {};
  const sizeInput = document.getElementById('radio-size-SMA003');
  if (sizeInput) {
    let p = sizeInput, chain = [];
    for (let i = 0; i < 6 && p; i++) { p = p.parentElement; if (!p) break; chain.push({ tag: p.tagName, cls: (p.className||'').toString().slice(0,70), id: p.id, vis: !!(p.offsetWidth||p.offsetHeight) }); }
    out.chain = chain;
    // label for this input
    const lbl = sizeInput.closest('label') || document.querySelector('label[for="radio-size-SMA003"]');
    out.label = lbl ? { tag: lbl.tagName, cls: (lbl.className||'').toString().slice(0,60), text: (lbl.innerText||'').trim().slice(0,40), vis: !!(lbl.offsetWidth||lbl.offsetHeight) } : null;
    out.inputAttrs = {};
    [...sizeInput.attributes].forEach(a => out.inputAttrs[a.name] = a.value.slice(0,60));
  }
  // all size option labels
  out.sizeOpts = [...document.querySelectorAll('[id^="radio-size-"]')].map(i => {
    const l = i.closest('label') || document.querySelector(`label[for="${i.id}"]`);
    return { id: i.id, txt: l ? (l.innerText||'').trim().slice(0,30) : null, vis: !!(i.offsetWidth||i.offsetHeight) };
  });
  // accordion expanded states
  out.acc = [...document.querySelectorAll('.accordion__label-wrapper')].slice(0,15).map(b => ({ txt: (b.innerText||'').trim().slice(0,25), exp: b.getAttribute('aria-expanded'), vis: !!(b.offsetWidth||b.offsetHeight) }));
  // any anchors with size-ish query params anywhere
  out.hrefs = [...new Set([...document.querySelectorAll('a[href]')].map(a=>a.getAttribute('href')).filter(h=>/size|Size|SMA/.test(h)))].slice(0,10);
  return out;
});
